            self.is_right(),
            self.has_resource(),
            self.is_valid(),
        ensures
            withdraws(self, SumSP::Right(None, self.frac(), true), imap![()=>self.resource()]),
    {
    }

    pub proof fn lemma_deposit_left(self, a: A)
        requires
